const execution = $input.first().json.execution;
const workflowName = execution.workflow ? execution.workflow.name : 'Unknown Workflow';
const lastNode = execution.lastNodeExecuted || 'Unknown Node';
const errorObj = execution.error || {};
const errorMessage = (errorObj.message || 'Unknown error occurred').slice(0, 300);

return [{
  json: {
    workflow: workflowName,
    executionId: execution.id || 'N/A',
    failedNode: lastNode,
    message: errorMessage,
    occurredAt: new Date().toISOString()
  }
}];

